head.script:
scwin.checkValue = function(id) {
    if (WebSquare.wUnit.getDomById($p.id + id)) {
        return true;
    }
    return false
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 6. 브라우저에서 그리드뷰의 헤더 셀렉트박스를 열고 임의의 데이터를 선택한다.
    //6. In the browser, open the header select box in the grid view and select any data.
    WebSquare.wUnit.addCommand("pause", "500");	
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wframe1_mf_wframe1_wq_uuid_12_head_selectbox_column3_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wframe1_mf_wframe1_wq_uuid_12_head_selectbox_column3_itemTable').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wframe1_mf_wframe1_wq_uuid_12_head_selectbox_column3_itemTable_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wframe2_mf_wframe2_wq_uuid_18_head_selectbox_column3_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wframe2_mf_wframe2_wq_uuid_18_head_selectbox_column3_itemTable').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wframe2_mf_wframe2_wq_uuid_18_head_selectbox_column3_itemTable_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 6. onChangeFunction 기능이 호출되어 'onChange2' 팝업이 생성된다. (그전버전에서는 1번 그림처럼 오류가 발생함.)
    //6. The onChangeFunction function is called to create the 'onChange2' popup. (In earlier versions, an error occurs, as shown in picture 1.)
    WebSquare.wUnit.addCommand("assert", "log", "true");
    WebSquare.wUnit.addCommand("assert", "log1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 12-Feb-2018
    //End unitTest
}
